<?php
 namespace QQWorld\ConfigurableProduct\Test\Unit\Ui\DataProvider\Product\Form\Modifier; use QQWorld\ConfigurableProduct\Ui\DataProvider\Product\Form\Modifier\StockData as StockDataModifier; use QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager as ObjectManagerHelper; use QQWorld\Catalog\Model\Locator\LocatorInterface; use QQWorld\Catalog\Api\Data\ProductInterface; class StockDataTest extends \PHPUnit\Framework\TestCase { private $stockDataModifier; private $objectManagerHelper; private $productLocatorMock; private $productMock; protected function setUp() { $this->productLocatorMock = $this->getMockBuilder(LocatorInterface::class) ->getMockForAbstractClass(); $this->productMock = $this->getMockBuilder(ProductInterface::class) ->getMockForAbstractClass(); $this->productLocatorMock->expects(static::any()) ->method('getProduct') ->willReturn($this->productMock); $this->objectManagerHelper = new ObjectManagerHelper($this); $this->stockDataModifier = $this->objectManagerHelper->getObject( StockDataModifier::class, [ 'locator' => $this->productLocatorMock ] ); } public function testModifyMeta() { $this->assertArrayHasKey('advanced_inventory_modal', $this->stockDataModifier->modifyMeta([])); } } 